package ai.eva.android.probe;
import android.content.Context;import android.graphics.BitmapFactory;import android.webkit.*;import android.net.Uri;import org.json.*;import java.io.*;import java.security.*;import java.util.*;
/** Persist generated image bytes separately from the compact UI state. */
final class GeneratedImages {
 static void normalize(Context c,JSONObject row){try{if("imageGeneration".equals(row.optString("type"))){String result=row.optString("result","");if(!result.isEmpty()&&!result.startsWith("http")&&!result.startsWith("/")){String raw=result.startsWith("data:image/")?result.substring(result.indexOf(',')+1):result;if(raw.length()<=33554432&&raw.matches("[A-Za-z0-9+/=\\r\\n]+")){byte[] bytes=android.util.Base64.decode(raw,android.util.Base64.DEFAULT);BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth>0&&options.outHeight>0&&Arrays.asList("image/png","image/jpeg","image/webp","image/gif").contains(options.outMimeType)){StringBuilder hash=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))hash.append(String.format("%02x",b&255));String name="generated-images/"+hash+".img";File file=WorkspaceFiles.resolve(c,name);synchronized(GeneratedImages.class){if(!file.exists()){file.getParentFile().mkdirs();File temp=new File(file.getPath()+".part");try(FileOutputStream out=new FileOutputStream(temp)){out.write(bytes);}if(!temp.renameTo(file))throw new IOException("Cannot save generated image");}}row.put("savedPath","/root/eva-workspace/"+name).put("result","").put("imageMime",options.outMimeType).put("imageWidth",options.outWidth).put("imageHeight",options.outHeight);}}}}
 for(String key:new String[]{"params","result","thread","turn","item"}){Object value=row.opt(key);if(value instanceof JSONObject)normalize(c,(JSONObject)value);}for(String key:new String[]{"items","turns"}){JSONArray values=row.optJSONArray(key);if(values!=null)for(int i=0;i<values.length();i++){JSONObject value=values.optJSONObject(i);if(value!=null)normalize(c,value);}}}catch(Exception ignored){/* Keep original event available for fallback rendering. */}}
 static void check(Context c){new Thread(()->{String result;try{JSONObject item=new JSONObject().put("type","imageGeneration").put("status","completed").put("result","");normalize(c,item);String path=item.getString("savedPath");if(!item.getString("result").isEmpty())throw new IOException("Inline payload retained");WebResourceResponse media=serve(c,Uri.parse("https://eva.invalid/generated-image?path="+Uri.encode(path)));if(media.getStatusCode()!=200||!"image/png".equals(media.getMimeType()))throw new IOException("Media not readable");try(InputStream in=media.getData()){if(in.read()!=137)throw new IOException("PNG signature mismatch");}WebResourceResponse denied=serve(c,Uri.parse("https://eva.invalid/generated-image?path="+Uri.encode("/root/eva-workspace/../.eva-codex/auth.json")));if(denied.getStatusCode()!=404)throw new IOException("Path escape accepted");result="PASS generated image persistence, payload removal, PNG serving and path escape rejection";}catch(Exception e){result="FAIL "+e;}android.util.Log.i("EvaImageCheck",result);},"eva-image-check").start();}
 static WebResourceResponse serve(Context c,Uri uri){try{String path=uri.getQueryParameter("path");if(path==null||!path.startsWith("/root/eva-workspace/"))throw new IOException("Unsupported path");File file=WorkspaceFiles.resolve(c,path.substring("/root/eva-workspace/".length()));if(!file.isFile()||file.length()>25165824)throw new IOException("Image missing or too large");BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),options);if(options.outWidth<=0||options.outHeight<=0||!Arrays.asList("image/png","image/jpeg","image/webp","image/gif").contains(options.outMimeType))throw new IOException("Unsupported image");return new WebResourceResponse(options.outMimeType,null,200,"OK",Collections.singletonMap("Cache-Control","private, max-age=3600"),new FileInputStream(file));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}}
}
